class TimezoneDataLoader{constructor(){this.data=null;this.isLoaded=false;this._loadPromise=null;}async load(){if (this.isLoaded)return this.data;if (this._loadPromise)return this._loadPromise;this._loadPromise=this._fetchData();return this._loadPromise;}async _fetchData(){try{const response=await fetch('/api/timezones',{headers:{'Accept':'application/json'},});if (!response.ok){throw new Error(`HTTP ${response.status}:${response.statusText}`);}this.data=await response.json();this.isLoaded=true;if (this.data.cities){window.ALL_CITIES=this.data.cities;}if (this.data.timezones){window.ALL_TIMEZONES=this.data.timezones;}console.log('[TimezoneLoader]时区数据加载成功');return this.data;}catch (error){console.error('[TimezoneLoader]加载失败:',error.message);this._loadPromise=null;throw error;}}async loadWithRetry(maxRetries=3,delayMs=1000){for (let i=0;i<maxRetries;i++){try{return await this.load();}catch (error){if (i===maxRetries-1){console.error('[TimezoneLoader]所有重试均失败');this._showFallbackUI();throw error;}console.warn(`[TimezoneLoader]第 ${i+1}次重试...`);await new Promise(resolve=>setTimeout(resolve,delayMs));}}}_showFallbackUI(){const containers=['#timezone-converter','.converter-section','.main-content'];let container=null;for (const selector of containers){container=document.querySelector(selector);if (container)break;}if (container){container.innerHTML=`<div class="error-state" role="alert" style="text-align:center;padding:48px 24px;"><div style="font-size:4rem;margin-bottom:16px;">&#9888;&#65039;</div><h3 style="margin-bottom:12px;color:var (--text);">Data Loading Failed</h3><p style="color:var (--text-muted);margin-bottom:20px;">Unable to load timezone data. Please check your network connection.</p><button onclick="location.reload()" class="btn" style="
display:inline-block;padding:12px 24px;background:var (--primary);color:white;border:none;border-radius:8px;cursor:pointer;font-size:1rem;">Refresh Page</button><p style="color:var (--text-muted);font-size:0.85rem;margin-top:16px;">If the problem persists,contact<a href="mailto:support@globetimezone.com">support@globetimezone.com</a></p></div>`;}}getData(){return this.data;}getCities(){return this.data?(this.data.cities||[]):[];}getTimezones(){return this.data?(this.data.timezones||[]):[];}}const tzLoader=new TimezoneDataLoader();if (document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>{tzLoader.loadWithRetry().then(()=>{console.log('[TimezoneLoader]就绪，触发应用初始化');if (typeof initApp==='function'){initApp();}}).catch (()=>{});});}else{tzLoader.loadWithRetry().then(()=>{if (typeof initApp==='function'){initApp();}}).catch (()=>{});}